    51	func (d *DB) IsInitialized(ctx context.Context) (bool, error) {
    52		var exists bool
    53		err := d.db.QueryRowContext(ctx, "SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'memo' AND TABLE_TYPE = 'BASE TABLE')").Scan(&exists)
    54		if err != nil {
    55			return false, errors.Wrap(err, "failed to check if database is initialized")
    56		}
    57		return exists, nil
    58	}
